536:     joystick.setPointerCapture?.(e.pointerId);
537:     joystick.classList.add('active');
538:     setJoystick(e);
539:     e.preventDefault();
540:   });
541:   joystick.addEventListener('pointermove', (e) => {
542:     if (e.pointerId !== joystickId) return;
543:     setJoystick(e);
544:     e.preventDefault();
545:   });
546:   joystick.addEventListener('pointerup', (e) => {
