559: // ======================= LOOP PRINCIPAL =======================
560: function frame(now) {
561:   const rawDt = (now - lastFrame) / 1000;
562:   const dt = clamp(Number.isFinite(rawDt) ? rawDt : 0.016, 0, 0.05);
563:   lastFrame = now;
564: 
565:   if (game) {
566:     game.update(dt);
567:     if (renderer) renderer.draw(dt);
568: 
569:     hudTimer += dt;
570:     if (hudTimer >= 0.2) {
571:       hudTimer = 0;
572:       ui.refreshHUD();
573:       if (mp && ui.el.mpRoster && !ui.el.mpRoster.classList.contains('hidden')) ui._refreshRoster();
574:     }
575: 
576:     minimapTimer += dt;
577:     if (minimapTimer >= 0.32 && !ui.el.hud?.classList.contains('hidden')) {
578:       minimapTimer = 0;
579:       const mini = document.getElementById('minimap');
580:       if (mini && renderer) renderer.drawMinimap(mini);
581:       if (!ui.el.mapScreen?.classList.contains('hidden') && renderer) renderer.drawFullMap(ui.el.mapCanvas);
582:     }
583: 
584:     // Atualiza o prompt de interação com um pouco mais de frequência.
585:     if (!ui.isAnyOverlayOpen()) ui.refreshHUD(false);
586:   } else {
587:     ui.animateMenu(dt);
588:   }
589: 
590:   // Contadores leves para diagnóstico.
591:   fpsAccum += dt;
592:   fpsFrames++;
593:   if (fpsAccum >= 1) {
594:     fps = Math.round(fpsFrames / fpsAccum);
595:     fpsAccum = 0;
596:     fpsFrames = 0;
597:     ui.el.fpsLabel?.remove();
598:   }
599: 
600:   requestAnimationFrame(frame);
601: }
