603: // ======================= CICLO DE ABA / PERSISTÊNCIA =======================
604: document.addEventListener('visibilitychange', () => {
605:   if (document.hidden && game?.mode === 'single' && !game.dead) ui.autosave(true);
606: });
607: 
608: window.addEventListener('beforeunload', () => {
609:   if (game?.mode === 'single' && !game.dead) ui.autosave(true);
610: });
611: 
612: window.addEventListener('error', (e) => {
613:   console.error('Erro em tempo de execução:', e.error || e.message);
614: });
615: window.addEventListener('unhandledrejection', (e) => {
616:   console.error('Promessa rejeitada:', e.reason);
617: });
